# owner: platform
"""Contact sheet rows for substitute teachers."""

from typing import List, Tuple
from rosterkit.models import Student
from rosterkit.errors import ProjectError


def _validate(students: List[Student]) -> None:
    if not students:
        raise ProjectError("no students to list")
    for stud in students:
        if not (stud.email or "").strip():
            raise ProjectError(
                f"no email for {stud.display_name}"
            )


def _widths(students: List[Student]) -> Tuple[int, int]:
    return (
        max(len(item.display_name) for item in students),
        max(len(item.section) for item in students),
    )


def _sort_key(stud: Student) -> Tuple[str, str]:
    return (stud.display_name.casefold(), stud.student_id)


def _row(stud: Student, wide: Tuple[int, int]) -> str:
    return (
        f"{stud.display_name:<{wide[0]}}  "
        f"{stud.section:<{wide[1]}}  "
        f"{stud.email.strip()}"
    )


# ---
def contact_rows(students: List[Student]) -> List[str]:
    """Name, section and email rows sorted by name."""
    _validate(students)
    wide = _widths(students)
    ordered = sorted(students, key=_sort_key)
    return [_row(stud, wide) for stud in ordered]
